def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    outside = set()
    queue = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in outside:
                outside.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                queue.append((nr, nc))

    interior = {(r, c) for r in range(h) for c in range(w)
                if grid[r][c] == 0 and (r, c) not in outside}

    eligible = set()
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            component = set()
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                component.add((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if any((x + dx, y + dy) in interior for x, y in component
                   for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                eligible.update(component)

    for r, c in interior:
        if any(0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 1
               for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc):
            out[r][c] = 3

    for r, c in outside:
        if any((r + dr, c + dc) in eligible
               for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc):
            out[r][c] = 2

    return out
